  'Chronic and Infectious Diseases',
  'An upper-division public health course on the population burden, determinants, prevention, surveillance, and control of major chronic and infectious diseases. The course uses epidemiologic methods, official datasets, case studies, and program design to connect disease biology with prevention systems, policy, ethics, equity, and implementation.',
  $cidjson${"slug": "chronic-and-infectious-diseases", "title": "Chronic and Infectious Diseases", "description": "An upper-division public health course on the population burden, determinants, prevention, surveillance, and control of major chronic and infectious diseases. The course uses epidemiologic methods, official datasets, case studies, and program design to connect disease biology with prevention systems, policy, ethics, equity, and implementation.", "topics": [{"id": "17ddb374-3346-48a7-ae85-396a823132f9", "type": "topic", "title": "Disease Burden, Epidemiologic Measures, and Comparative Risk", "description": "This opening section gives students the measurement language needed to compare diseases, prioritize action, and interpret public health claims. It turns disease lists into accountable population health decisions.", "children": [{"id": "1c99d561-5505-4048-b526-3f7fc9125064", "type": "subtopic", "title": "Burden of disease concepts", "description": "This subtopic teaches students how public health compares diseases across populations instead of relying on anecdotes or raw case counts.", "children": [{"id": "04e3bcbe-3c70-45dc-b873-c18454df73d5", "type": "concept", "title": "Incidence, prevalence, mortality, case fatality, and years of potential life lost"}, {"id": "cfc47bf5-f4c7-4402-a687-6b45d5859f91", "type": "concept", "title": "DALYs, QALYs, disability weights, and summary measures"}, {"id": "c1badace-38ad-4350-bac3-171446be1f62", "type": "concept", "title": "Age standardization and comparison across places or time"}]}, {"id": "1d219f24-e57a-4512-bf51-71f4baf14a14", "type": "subtopic", "title": "Risk factors and causal framing", "description": "The goal is to connect patterns of disease to modifiable exposures and plausible causal pathways.", "children": [{"id": "0300293f-b304-49f1-b28a-a82a88af35c6", "type": "concept", "title": "Behavioral, metabolic, environmental, infectious, occupational, and social risks"}, {"id": "7e22aa33-8bd0-44e7-9929-c2c20a6a40b7", "type": "concept", "title": "Causal webs and sufficient-component cause thinking"}, {"id": "91fc98db-bf0c-4bc1-bfd0-3f265798ff20", "type": "concept", "title": "Population attributable fraction and preventable burden"}]}, {"id": "8a198eff-b49c-4268-99cb-82321ed47dec", "type": "subtopic", "title": "Data interpretation and uncertainty", "description": "Students learn to read disease estimates with appropriate caution, especially when comparing groups or countries.", "children": [{"id": "2d0ee67d-6df1-4e07-bd59-344c1752f6df", "type": "concept", "title": "Confidence intervals and measurement error"}, {"id": "9a9afe03-5666-4da7-b140-d67bc77e952f", "type": "concept", "title": "Underreporting, misclassification, and surveillance bias"}, {"id": "bf4fb964-8551-4f64-83c4-ec3d8bd5ec09", "type": "concept", "title": "Communicating uncertainty without weakening action"}]}]}, {"id": "fa0fd8dd-283f-4303-b1fa-83f23f105e66", "type": "topic", "title": "Chronic Disease Epidemiology, Prevention, and Life-Course Risk", "description": "This section establishes chronic disease as a product of cumulative risk, social conditions, prevention systems, and long-term care, not simply individual choices.", "children": [{"id": "23600c04-18e9-47e0-b371-d2d10e4a1773", "type": "subtopic", "title": "Chronic disease as a population problem", "description": "This section frames chronic disease as an accumulation of risk across life, policy, environment, and care systems.", "children": [{"id": "03297600-2eaf-43be-bf1c-3faa1c8888d6", "type": "concept", "title": "Life-course exposure and latency"}, {"id": "3edbf10b-ebbe-448c-ab4c-1e91e0aaf774", "type": "concept", "title": "Primary, secondary, and tertiary prevention"}, {"id": "ccaba10f-5a24-4490-b4d8-de8b8413aca3", "type": "concept", "title": "Multilevel determinants from biology to policy"}]}, {"id": "90c1c4d3-a6af-4bb2-a6b4-73c9807d1423", "type": "subtopic", "title": "Screening and prevention logic", "description": "Students learn why screening can help, harm, or waste resources depending on test performance and disease context.", "children": [{"id": "d42beb62-e6eb-4b01-a4c1-e4d7e52e3b69", "type": "concept", "title": "Sensitivity, specificity, predictive value, and lead-time bias"}, {"id": "3c912195-24fe-4d10-afe8-f6ca286a2bd0", "type": "concept", "title": "Screening eligibility and risk stratification"}, {"id": "f066473d-eea6-4a3f-8e35-600c566c5ff4", "type": "concept", "title": "Overdiagnosis, overtreatment, and informed choice"}]}, {"id": "a1041243-65ba-4eea-a4e0-991855ba478c", "type": "subtopic", "title": "Chronic disease surveillance", "description": "The gist is to understand how health departments monitor trends and evaluate prevention programs.", "children": [{"id": "8156d56e-3f8d-4d60-9d1f-9477eb2d26f2", "type": "concept", "title": "BRFSS, NHANES, registries, claims, and vital statistics"}, {"id": "e2f8a382-5b7e-481b-a3e0-b3aea3ff5d60", "type": "concept", "title": "Risk-factor monitoring and health indicators"}, {"id": "599c5cef-913b-4561-bb72-25ce98b21788", "type": "concept", "title": "Dashboards, targets, and Healthy People objectives"}]}]}, {"id": "61d1d964-05bc-4343-beda-5696618613bd", "type": "topic", "title": "Cardiovascular Disease and Stroke Prevention", "description": "This topic treats cardiovascular disease and stroke as major preventable causes of death, disability, and inequity, with attention to clinical prevention and upstream policy.", "children": [{"id": "1c425996-c96a-4a6e-b962-bea2eedb8dd1", "type": "subtopic", "title": "Epidemiology of cardiovascular disease", "description": "Students examine why heart disease and stroke remain leading causes of death and disability.", "children": [{"id": "d68beacf-1f30-4a05-a734-85b92ee8ec52", "type": "concept", "title": "Coronary heart disease, heart failure, stroke, and hypertension"}, {"id": "9054fa69-f198-4e06-b499-8954b69a23d0", "type": "concept", "title": "Age, sex, race, geography, and socioeconomic gradients"}, {"id": "bf0b56bc-eaf2-4f2f-9950-2509ad3d68e0", "type": "concept", "title": "Mortality decline, stagnation, and emerging risk patterns"}]}, {"id": "e7790e9c-7f87-426b-9281-3e84d46bcc03", "type": "subtopic", "title": "Risk factors and prevention", "description": "This subtopic links individual risk reduction with upstream prevention.", "children": [{"id": "3b7b64e7-e36b-44fa-a9c1-09aa05185d5d", "type": "concept", "title": "Blood pressure, cholesterol, smoking, diabetes, diet, physical activity, and air pollution"}, {"id": "cafe6d3e-6f8c-4367-ae79-951980043de1", "type": "concept", "title": "Risk prediction and population-wide prevention"}, {"id": "62b3ea52-9c46-4335-a837-e95f2643e018", "type": "concept", "title": "Salt reduction, tobacco control, built environment, and clinical prevention"}]}, {"id": "a2a68356-20fb-4fd4-a754-12866af30c6f", "type": "subtopic", "title": "Systems of care and outcomes", "description": "Learners connect prevention with emergency response, rehabilitation, and long-term secondary prevention.", "children": [{"id": "8e495047-8e34-487c-9a43-332f300c9c50", "type": "concept", "title": "EMS and stroke systems of care"}, {"id": "fe4255ac-b77f-46aa-b848-3d31534e9a99", "type": "concept", "title": "Medication adherence and secondary prevention"}, {"id": "339825f4-aa41-440c-9cd1-3bb52a5937aa", "type": "concept", "title": "Cardiac rehabilitation and community support"}]}]}, {"id": "1ef5460f-0291-4f8f-b54d-defdae95b146", "type": "topic", "title": "Cancer Epidemiology, Screening, and Control", "description": "This section gives students a public health view of cancer across prevention, screening, early detection, treatment access, survivorship, and population monitoring.", "children": [{"id": "d170eb13-a818-4c5a-a4da-1a0bbf450b34", "type": "subtopic", "title": "Cancer burden and natural history", "description": "Students learn cancer as a set of diseases shaped by genetics, exposures, infection, screening, treatment access, and survivorship.", "children": [{"id": "cf191f89-98bf-411b-90d8-35c0f6bbb4c5", "type": "concept", "title": "Incidence, mortality, stage, and survival"}, {"id": "16e2e4c7-3e49-4127-a88f-0737a9270215", "type": "concept", "title": "Cancer registries and population monitoring"}, {"id": "0fc95105-371d-4bc6-bf60-0f70506842bb", "type": "concept", "title": "Latency, carcinogenesis, and modifiable exposure"}]}, {"id": "b254b62a-d49e-4634-9fe7-5c03e9630e4a", "type": "subtopic", "title": "Major preventable cancers", "description": "The point is to see how prevention extends beyond clinical treatment.", "children": [{"id": "6d4843bd-c80f-4342-86bd-2d6d39c66a40", "type": "concept", "title": "Tobacco-related cancers"}, {"id": "088e84cc-9039-4088-bd72-fd894364a438", "type": "concept", "title": "HPV, hepatitis B/C, and infection-associated cancers"}, {"id": "84bd3515-d7ba-44a5-89cd-78a9c8a8b9c0", "type": "concept", "title": "Occupational, environmental, diet, alcohol, and UV exposure"}]}, {"id": "12a1f764-b990-44d2-8bea-8397ef7dd895", "type": "subtopic", "title": "Screening, control, and survivorship", "description": "Learners evaluate evidence-based cancer control strategies and their equity implications.", "children": [{"id": "5e2e91b1-5d3b-4c86-88c2-fd477109d942", "type": "concept", "title": "Breast, cervical, colorectal, lung, and prostate screening controversies"}, {"id": "cfb7b990-b255-46d8-997e-4932a6602b57", "type": "concept", "title": "Access to diagnosis, treatment, and palliative care"}, {"id": "b26c526e-56a8-4e65-b12e-cc5658e78628", "type": "concept", "title": "Survivorship, late effects, and financial toxicity"}]}]}, {"id": "24925a67-871d-4d58-a6c6-9427dddb2f69", "type": "topic", "title": "Diabetes, Obesity, Metabolic Health, and Nutrition-Related Disease", "description": "This topic links metabolic disease to food systems, built environments, chronic care, and inequitable access to prevention and treatment.", "children": [{"id": "676e8538-6305-4b82-8bb2-934ac3be8a0b", "type": "subtopic", "title": "Metabolic disease burden", "description": "This subtopic shows how diabetes and obesity reflect both individual physiology and population environments.", "children": [{"id": "8fd52a60-57d6-4d44-a91a-0eb015182ef6", "type": "concept", "title": "Type 1, type 2, gestational diabetes, and prediabetes"}, {"id": "486250be-1a1e-4431-b4cd-8063af3381ec", "type": "concept", "title": "Obesity, metabolic syndrome, and cardiometabolic risk"}, {"id": "0b4f7576-b0e8-414d-97f8-d0a20c526a64", "type": "concept", "title": "Complications including kidney, eye, nerve, and vascular disease"}]}, {"id": "ea9ca584-8101-4957-8008-2ff455a81135", "type": "subtopic", "title": "Food systems and activity environments", "description": "Students connect metabolic risk to food access, marketing, housing, transportation, and work conditions.", "children": [{"id": "df75795a-2bce-46e7-8154-d13dbd829acd", "type": "concept", "title": "Food insecurity and ultra-processed foods"}, {"id": "e8e83028-ddcc-4309-90b2-267eaccd4239", "type": "concept", "title": "Physical activity, sedentary behavior, and built environment"}, {"id": "4d282a60-eee7-46c4-b2b0-9db61b71ba6b", "type": "concept", "title": "Policy tools such as labeling, procurement, taxes, and subsidies"}]}, {"id": "adcef5e4-e3ab-4c73-9a4f-48e33929cbb1", "type": "subtopic", "title": "Prevention and disease management", "description": "The gist is to integrate community prevention with evidence-based chronic care.", "children": [{"id": "b743ad03-04a6-4293-afaa-123ec9c40f78", "type": "concept", "title": "Diabetes Prevention Program and lifestyle interventions"}, {"id": "6394fd46-3d86-4912-9871-64419cf143f5", "type": "concept", "title": "Screening and risk identification"}, {"id": "5e139fc8-c53d-40e6-9f08-d7102338f343", "type": "concept", "title": "Self-management support, team-based care, and digital tools"}]}]}, {"id": "0e318301-6105-4922-bd9c-d5c7eed23d1f", "type": "topic", "title": "Mental Health, Substance Use, Disability, and Multimorbidity", "description": "This section makes behavioral health and multimorbidity central to disease burden, prevention planning, and compassionate public health practice.", "children": [{"id": "e3cdfee7-d657-4d09-a02c-5dcfc8df4584", "type": "subtopic", "title": "Population mental health", "description": "Students learn that mental health is central to public health burden, not separate from it.", "children": [{"id": "950620f9-4609-42a4-81a3-835313a12a57", "type": "concept", "title": "Depression, anxiety, serious mental illness, suicide, and trauma"}, {"id": "e2cf6d4e-eb09-481d-ad54-b724df0f235f", "type": "concept", "title": "Measurement, stigma, access, and unmet need"}, {"id": "c1effd7e-ed6a-4519-bdce-b85f53642423", "type": "concept", "title": "School, workplace, community, and crisis-system prevention"}]}, {"id": "f0a2fd7b-2ffa-4cf1-88ed-63376a7e73ba", "type": "subtopic", "title": "Substance use and overdose", "description": "This subtopic links epidemiology, harm reduction, treatment access, policy, and structural risk.", "children": [{"id": "418ccda6-6483-47c4-ba03-ba52ad99147b", "type": "concept", "title": "Alcohol, opioids, stimulants, tobacco, and polysubstance use"}, {"id": "45e53471-0ce0-41f5-83dc-6334030416f3", "type": "concept", "title": "Overdose surveillance and mortality trends"}, {"id": "013e2d71-5244-4df5-bc6c-852194b10a82", "type": "concept", "title": "Naloxone, medications for opioid use disorder, syringe services, and prevention"}]}, {"id": "00987704-c045-4593-a174-000057afa8e7", "type": "subtopic", "title": "Multimorbidity and disability", "description": "Learners examine how chronic disease clusters and disability change prevention priorities.", "children": [{"id": "04aaf90d-a5ae-47b6-be14-a229aed4d98a", "type": "concept", "title": "Comorbidity patterns across age groups"}, {"id": "d5f2ba86-60bd-4695-9c07-a5becffd0987", "type": "concept", "title": "Functional status, disability-adjusted outcomes, and caregiver burden"}, {"id": "9013aab0-35c4-4b01-811b-e1f66c5b717f", "type": "concept", "title": "Integrated care for physical, behavioral, and social needs"}]}]}, {"id": "86ae311f-3804-4cfe-bacf-d618e260ecf1", "type": "topic", "title": "Chronic Respiratory Disease, Environmental Exposure, and Occupational Risk", "description": "This topic connects chronic respiratory disease to air quality, housing, climate, occupational hazards, tobacco policy, and environmental justice.", "children": [{"id": "dd56429d-028f-4e27-a4d7-2bb41848ac6b", "type": "subtopic", "title": "Respiratory disease burden", "description": "Students study asthma, COPD, occupational lung disease, and respiratory disability as preventable population problems.", "children": [{"id": "163dd0ac-3483-4aac-95b2-cfe05ba2d0cb", "type": "concept", "title": "Asthma prevalence and exacerbations"}, {"id": "7063dbcb-1553-4a82-b1c0-b08ad760a665", "type": "concept", "title": "COPD, smoking, biomass exposure, and aging"}, {"id": "9a1bd7a4-645b-4cad-b7e7-e258fcd51be3", "type": "concept", "title": "Occupational lung disease and environmental justice"}]}, {"id": "78a030b7-ff63-44e0-9285-28183e8756b1", "type": "subtopic", "title": "Environmental and climate exposures", "description": "The point is to connect air, housing, climate, and workplace conditions to chronic respiratory outcomes.", "children": [{"id": "4f06ece5-7c8c-456a-b93c-82ec0ac13180", "type": "concept", "title": "Outdoor air pollution, wildfire smoke, and ozone"}, {"id": "db0b63a8-f7a7-4b6e-8830-b7ae72392ffb", "type": "concept", "title": "Indoor air, mold, allergens, and housing quality"}, {"id": "7387d904-fc96-4ac3-9ff9-983ef90c9c04", "type": "concept", "title": "Heat, climate events, and respiratory vulnerability"}]}, {"id": "794b1fea-bcb0-478e-ac48-478c9d48c927", "type": "subtopic", "title": "Prevention and management programs", "description": "Learners translate exposure control into interventions at home, school, workplace, and policy levels.", "children": [{"id": "40120c19-50bd-45d8-8cbc-9d41de7f085a", "type": "concept", "title": "Tobacco control and smoke-free policy"}, {"id": "a8fb44fd-00ea-4fc6-afec-3cf49a75410d", "type": "concept", "title": "Asthma home visiting and trigger reduction"}, {"id": "315cd692-1c5c-42ff-821a-c4751219cf23", "type": "concept", "title": "Occupational standards, monitoring, and enforcement"}]}]}, {"id": "02752335-e239-4d06-ba0d-e9309f6e196c", "type": "topic", "title": "Infectious Disease Epidemiology, Transmission, and Surveillance", "description": "This section builds the transmission, surveillance, and outbreak investigation skills needed to move from individual cases to population control.", "children": [{"id": "4548a311-76a7-4b96-9792-f9be79fb1c8f", "type": "subtopic", "title": "Transmission principles", "description": "This section teaches the core logic of how infections spread through people, places, vectors, and systems.", "children": [{"id": "dbabb614-a00f-4b1f-97eb-d5d10de3bd10", "type": "concept", "title": "Reservoirs, modes of transmission, incubation, infectious period, and susceptibility"}, {"id": "878ea987-9a24-4446-8d78-47c7fecb2cfb", "type": "concept", "title": "R0, effective reproduction number, herd protection, and attack rates"}, {"id": "d954564f-116b-4c1d-9bcb-d55b813969a8", "type": "concept", "title": "Chain of infection and points of intervention"}]}, {"id": "8152d525-827d-4a2e-bb5d-7e7d87147a0f", "type": "subtopic", "title": "Surveillance systems", "description": "Students learn how cases become data and how data become public health action.", "children": [{"id": "2596efc5-0b67-4053-a090-25beee9f025c", "type": "concept", "title": "Notifiable disease reporting"}, {"id": "8e78eec3-e972-4d32-b58c-4be8e2934f14", "type": "concept", "title": "Syndromic, sentinel, laboratory, genomic, and wastewater surveillance"}, {"id": "a6c3eb66-7896-489a-bd2a-ef61a8c3ded3", "type": "concept", "title": "Data timeliness, completeness, privacy, and representativeness"}]}, {"id": "e484722c-feb9-47c0-8d90-5e7cc0b10ea7", "type": "subtopic", "title": "Outbreak investigation", "description": "The gist is to move from signal detection to control measures using a disciplined field method.", "children": [{"id": "81e2aadd-18a5-4984-91c1-3b34633d291d", "type": "concept", "title": "Case definitions, line lists, descriptive epidemiology, and epidemic curves"}, {"id": "006a594a-0636-4f34-ac81-ce2a49ea2df7", "type": "concept", "title": "Hypothesis generation, analytic studies, and environmental assessment"}, {"id": "407bc069-fbb8-450d-b144-bb223c39f44c", "type": "concept", "title": "Risk communication and after-action review"}]}]}, {"id": "b3b3ff7b-377d-4e96-a0dd-0cc1bbb71bf9", "type": "topic", "title": "HIV/AIDS, Sexually Transmitted Infections, and Viral Hepatitis", "description": "This topic integrates biomedical prevention, testing, treatment, stigma reduction, partner services, and structural determinants in sexual and bloodborne infections.", "children": [{"id": "f9091701-48a2-46e5-ace2-2e631e6d83f4", "type": "subtopic", "title": "HIV epidemiology and prevention", "description": "Students learn HIV as a biomedical, behavioral, structural, and human-rights public health challenge.", "children": [{"id": "423c3732-21fc-4e42-9a79-d211afc91c27", "type": "concept", "title": "Testing, linkage, retention, viral suppression, and U equals U"}, {"id": "07b70bec-b786-47a6-8a67-b9aa3764339e", "type": "concept", "title": "PrEP, PEP, condom access, harm reduction, and partner services"}, {"id": "0621e34d-f0fd-44d9-8786-b86b6d233314", "type": "concept", "title": "Stigma, criminalization, racism, and disparities"}]}, {"id": "e314236c-c723-4dc2-87af-a6302021dff0", "type": "subtopic", "title": "STI control", "description": "This subtopic builds practical understanding of surveillance, screening, treatment, and prevention for common STIs.", "children": [{"id": "a67ae164-a756-4dde-8144-f6159ce0435b", "type": "concept", "title": "Chlamydia, gonorrhea, syphilis, HPV, and HSV"}, {"id": "4aea40e1-e678-46ad-bcf4-8f5c4279d7f1", "type": "concept", "title": "Screening recommendations and partner notification"}, {"id": "19d52939-987d-4746-a396-9cf03ced3796", "type": "concept", "title": "Congenital syphilis, antimicrobial resistance, and prevention gaps"}]}, {"id": "b413af28-e06b-4c36-975d-cce63e3aa011", "type": "subtopic", "title": "Viral hepatitis", "description": "Learners connect vaccination, screening, treatment, and harm reduction to liver disease prevention.", "children": [{"id": "daccc90c-0315-4840-a4ae-f4cd88c53283", "type": "concept", "title": "Hepatitis A, B, C, D, and E transmission patterns"}, {"id": "92a3b121-8f36-4251-832b-1e7c4bd4df11", "type": "concept", "title": "HBV vaccination and perinatal prevention"}, {"id": "bd544b6f-a5e6-4e58-851b-366f30271dbe", "type": "concept", "title": "HCV screening, curative therapy, and injection-related risk"}]}]}, {"id": "5042e2d5-c6ab-4b5c-865a-2e1190145b35", "type": "topic", "title": "Tuberculosis, Malaria, Neglected Tropical Diseases, and Vector-Borne Disease", "description": "This section broadens the course beyond high-income settings and shows how poverty, climate, migration, vectors, and health systems shape disease control.", "children": [{"id": "09312e26-51bb-4a5c-80a3-081392623965", "type": "subtopic", "title": "Tuberculosis control", "description": "Students examine TB as an airborne infectious disease shaped by poverty, housing, migration, immunity, and treatment completion.", "children": [{"id": "ad3258d8-0b22-425e-bbaa-61284b5fd3a2", "type": "concept", "title": "Latent TB infection and active TB disease"}, {"id": "67cf06c7-1730-45eb-a5c5-889d30c072d8", "type": "concept", "title": "Contact investigation and directly observed therapy"}, {"id": "5d3297f7-26f0-490e-bf4c-753eeb48d92b", "type": "concept", "title": "Drug resistance, diagnostics, and global control strategy"}]}, {"id": "78999a63-4874-40c1-8616-f26be887b477", "type": "subtopic", "title": "Malaria and vector-borne disease", "description": "The point is to understand how ecology, climate, vector control, and health systems shape disease risk.", "children": [{"id": "d8ac1f4c-385c-4ba1-9b92-594cee860bb8", "type": "concept", "title": "Malaria life cycle, diagnosis, prevention, and treatment access"}, {"id": "be584ef8-09f8-4217-926a-c9b1ea72b7dd", "type": "concept", "title": "Dengue, Zika, chikungunya, yellow fever, Lyme disease, and West Nile virus"}, {"id": "3e15a004-c439-406a-8e27-8dac31382b0d", "type": "concept", "title": "Vector surveillance, insecticide resistance, and environmental management"}]}, {"id": "ec43f769-e412-4435-9449-af7be0194259", "type": "subtopic", "title": "Neglected tropical diseases", "description": "Learners study diseases that persist where poverty, sanitation, climate, and access barriers overlap.", "children": [{"id": "02c25e5c-9260-4bf3-aa99-54e4fc9f7344", "type": "concept", "title": "Helminths, schistosomiasis, trachoma, leishmaniasis, Chagas disease, and lymphatic filariasis"}, {"id": "f8b4a82b-9a90-4180-8fc7-f7be9e7c351b", "type": "concept", "title": "Mass drug administration and integrated control"}, {"id": "4f1e489d-b0a5-44bd-b8cc-14ef3ed5e4e6", "type": "concept", "title": "Water, sanitation, housing, and community engagement"}]}]}, {"id": "179a470a-7390-47c6-8e13-23281b77b1c5", "type": "topic", "title": "Emerging Infections, Zoonoses, One Health, and Pandemic Preparedness", "description": "This topic prepares students to think across human, animal, and environmental systems while planning for fast-moving public health emergencies.", "children": [{"id": "996a4392-2e2c-4499-9bf0-d93065382d0e", "type": "subtopic", "title": "Emergence and re-emergence", "description": "Students learn why new threats arise and why old threats return.", "children": [{"id": "d7cba011-8dc0-4d86-90f3-e318a9c8ec9a", "type": "concept", "title": "Spillover, mutation, recombination, and pathogen adaptation"}, {"id": "70d3a68e-dbc9-4de6-be1f-23ed4169305a", "type": "concept", "title": "Land use, wildlife trade, agriculture, travel, conflict, and climate"}, {"id": "861736de-1284-468b-925d-1fa7f727dff2", "type": "concept", "title": "Re-emergence driven by vaccine gaps, resistance, and weakened systems"}]}, {"id": "da121ccc-56ac-4679-8d4f-45ee4c1275d5", "type": "subtopic", "title": "One Health systems", "description": "This subtopic integrates human, animal, and environmental health surveillance and prevention.", "children": [{"id": "f8eb2f2b-ca1c-413a-90d1-c7bd1566861a", "type": "concept", "title": "Zoonotic reservoirs and animal-human interfaces"}, {"id": "08137e3a-3ef6-4a94-b877-fc7cc2217d5f", "type": "concept", "title": "Food systems, antimicrobial use in agriculture, and biosafety"}, {"id": "39b27beb-b3a3-44c2-97e0-0b47b8858ebd", "type": "concept", "title": "Cross-sector coordination and data sharing"}]}, {"id": "cac3862d-c243-43b7-ac99-a5193d257005", "type": "subtopic", "title": "Preparedness and response", "description": "Learners build a practical view of readiness before, during, and after health emergencies.", "children": [{"id": "1f73cfff-9e9a-4ecf-bb7b-7a2d3b527b5a", "type": "concept", "title": "Incident management and emergency operations"}, {"id": "cb072d01-367c-4e35-a60c-77006b8c450f", "type": "concept", "title": "Testing, tracing, isolation, quarantine, and medical countermeasures"}, {"id": "b970105b-d665-4ce8-834d-d920dd55accb", "type": "concept", "title": "Community trust, misinformation, and continuity of essential services"}]}]}, {"id": "0dcb5a54-4be5-49f6-92fa-9ca2a81ae248", "type": "topic", "title": "Vaccines, Infection Prevention, Antimicrobial Resistance, and Control Programs", "description": "This section focuses on proven disease-control tools and the implementation challenges that determine whether they work in the real world.", "children": [{"id": "81d1c6fb-96ff-4a79-8e3f-906a59bb2d12", "type": "subtopic", "title": "Vaccinology and immunization programs", "description": "Students learn how vaccines work and what makes immunization programs succeed or fail.", "children": [{"id": "2265f4fe-5ed4-4cf0-a596-2823e8cfbf13", "type": "concept", "title": "Vaccine types, effectiveness, safety monitoring, and schedules"}, {"id": "f5eb119d-92d3-4901-8acc-b8a962f321a9", "type": "concept", "title": "Coverage, hesitancy, mandates, access, and equity"}, {"id": "c11c5be5-9562-4566-ba44-487a7f675605", "type": "concept", "title": "Outbreak control and catch-up vaccination"}]}, {"id": "31f887c7-4466-4cf5-a6f6-8618147f18f8", "type": "subtopic", "title": "Infection prevention and control", "description": "The goal is to understand everyday control practices that prevent transmission in healthcare and community settings.", "children": [{"id": "46733478-50b1-4cb8-845e-6f6820304e8b", "type": "concept", "title": "Standard, contact, droplet, and airborne precautions"}, {"id": "ee1beaff-9bdd-4f42-bb8a-5a060c93c59e", "type": "concept", "title": "Hand hygiene, PPE, ventilation, cleaning, and isolation"}, {"id": "18030456-a9e8-419a-861f-f8f77f0015a4", "type": "concept", "title": "Healthcare-associated infections and device-related risks"}]}, {"id": "449cddf1-8c6f-4b0d-be71-93251ca3fea9", "type": "subtopic", "title": "Antimicrobial resistance", "description": "Learners examine resistance as a public health, clinical, agricultural, and global governance challenge.", "children": [{"id": "85acf5dd-3b10-4775-aef6-4ceaedba0197", "type": "concept", "title": "Mechanisms and drivers of resistance"}, {"id": "8b14755c-3d85-4f39-a12c-3085f34d8468", "type": "concept", "title": "Antimicrobial stewardship and diagnostic stewardship"}, {"id": "bd118c92-115d-4b19-9101-50c1c986db86", "type": "concept", "title": "Surveillance, policy, and pipeline challenges"}]}]}, {"id": "c3fc9ca6-90c1-47f8-9c88-ef1b7bd0685d", "type": "topic", "title": "Integrated Disease Programs, Equity, Policy, and Capstone", "description": "The final section turns chronic and infectious disease evidence into an equitable, implementable public health plan.", "children": [{"id": "5ab1b3e6-8e91-4ab3-b27f-4549a5fc99e6", "type": "subtopic", "title": "Integrated prevention strategy", "description": "Students design programs that do not isolate chronic and infectious disease from social reality.", "children": [{"id": "8082cc38-8740-4014-a2ac-41a7db8418ca", "type": "concept", "title": "Coordinated screening, vaccination, harm reduction, and chronic care"}, {"id": "7de30b8a-1a95-4b84-a3bb-add539fbb860", "type": "concept", "title": "Primary care, community health workers, schools, workplaces, and public health departments"}, {"id": "4732a767-4f03-4e28-b818-5a7ecf5cf2d2", "type": "concept", "title": "Implementation science and sustainability"}]}, {"id": "2219abb9-0396-45ca-8f79-dc5b50b61eca", "type": "subtopic", "title": "Equity and ethics", "description": "Students learn to evaluate who benefits, who is burdened, and whose voice shapes disease control.", "children": [{"id": "a3adfef0-8d30-4423-93f4-6c7edebd9ea7", "type": "concept", "title": "Structural racism, poverty, disability, immigration, incarceration, and rurality"}, {"id": "4ca84c80-be4d-456d-8090-54070f6ffaff", "type": "concept", "title": "Stigma, coercion, privacy, and public good"}, {"id": "416b1984-00af-402e-ad49-73ddce1af170", "type": "concept", "title": "Community engagement and culturally responsive practice"}]}, {"id": "0d88aedb-9148-4951-b267-b4afe267a4e7", "type": "subtopic", "title": "Capstone translation", "description": "Learners convert evidence into a practical public health product for decision-makers.", "children": [{"id": "38667fd3-043b-49d8-a5fd-71b8bcee7830", "type": "concept", "title": "Problem statement, stakeholder map, and theory of change"}, {"id": "362e0548-2b62-407f-93fd-befc1b50794b", "type": "concept", "title": "Data brief, intervention plan, budget logic, and evaluation measures"}, {"id": "5d377536-b16b-4a0b-8c58-810988c9bf0b", "type": "concept", "title": "Policy memo, oral briefing, and implementation roadmap"}]}]}], "dbBacked": true}$cidjson$::jsonb,
