update public.learning_paths
set
  title = 'Chronic and Infectious Diseases',
  goal = 'Chronic and Infectious Diseases',
  summary = 'An upper-division public health course on the population burden, determinants, prevention, surveillance, and control of major chronic and infectious diseases. The course uses epidemiologic methods, official datasets, case studies, and program design to connect disease biology with prevention systems, policy, ethics, equity, and implementation.',
  data = $cidjson${"slug": "chronic-and-infectious-diseases", "title": "Chronic and Infectious Diseases", "description": "An upper-division public health course on the population burden, determinants, prevention, surveillance, and control of major chronic and infectious diseases. The course uses epidemiologic methods, official datasets, case studies, and program design to connect disease biology with prevention systems, policy, ethics, equity, and implementation.", "topics": [{"id": "17ddb374-3346-48a7-ae85-396a823132f9", "type": "topic", "title": "Disease Burden, Epidemiologic Measures, and Comparative Risk", "description": "This opening section gives students the measurement language needed to compare diseases, prioritize action, and interpret public health claims. It turns disease lists into accountable population health decisions.", "children": [{"id": "1c99d561-5505-4048-b526-3f7fc9125064", "type": "subtopic", "title": "Burden of disease concepts", "description": "This subtopic teaches students how public health compares diseases across populations instead of relying on anecdotes or raw case counts.", "children": [{"id": "04e3bcbe-3c70-45dc-b873-c18454df73d5", "type": "concept", "title": "Incidence, prevalence, mortality, case fatality, and years of potential life lost"}, {"id": "cfc47bf5-f4c7-4402-a687-6b45d5859f91", "type": "concept", "title": "DALYs, QALYs, disability weights, and summary measures"}, {"id": "c1badace-38ad-4350-bac3-171446be1f62", "type": "concept", "title": "Age standardization and comparison across places or time"}]}, {"id": "1d219f24-e57a-4512-bf51-71f4baf14a14", "type": "subtopic", "title": "Risk factors and causal framing", "description": "The goal is to connect patterns of disease to modifiable exposures and plausible causal pathways.", "children": [{"id": "0300293f-b304-49f1-b28a-a82a88af35c6", "type": "concept", "title": "Behavioral, metabolic, environmental, infectious, occupational, and social risks"}, {"id": "7e22aa33-8bd0-44e7-9929-c2c20a6a40b7", "type": "concept", "title": "Causal webs and sufficient-component cause thinking"}, {"id": "91fc98db-bf0c-4bc1-bfd0-3f265798ff20", "type": "concept", "title": "Population attributable fraction and preventable burden"}]}, {"id": "8a198eff-b49c-4268-99cb-82321ed47dec", "type": "subtopic", "title": "Data interpretation and uncertainty", "description": "Students learn to read disease estimates with appropriate caution, especially when comparing groups or countries.", "children": [{"id": "2d0ee67d-6df1-4e07-bd59-344c1752f6df", "type": "concept", "title": "Confidence intervals and measurement error"}, {"id": "9a9afe03-5666-4da7-b140-d67bc77e952f", "type": "concept", "title": "Underreporting, misclassification, and surveillance bias"}, {"id": "bf4fb964-8551-4f64-83c4-ec3d8bd5ec09", "type": "concept", "title": "Communicating uncertainty without weakening action"}]}]}, {"id": "fa0fd8dd-283f-4303-b1fa-83f23f105e66", "type": "topic", "title": "Chronic Disease Epidemiology, Prevention, and Life-Course Risk", "description": "This section establishes chronic disease as a product of cumulative risk, social conditions, prevention systems, and long-term care, not simply individual choices.", "children": [{"id": "23600c04-18e9-47e0-b371-d2d10e4a1773", "type": "subtopic", "title": "Chronic disease as a population problem", "description": "This section frames chronic disease as an accumulation of risk across life, policy, environment, and care systems.", "children": [{"id": "03297600-2eaf-43be-bf1c-3faa1c8888d6", "type": "concept", "title": "Life-course exposure and latency"}, {"id": "3edbf10b-ebbe-448c-ab4c-1e91e0aaf774", "type": "concept", "title": "Primary, secondary, and tertiary prevention"}, {"id": "ccaba10f-5a24-4490-b4d8-de8b8413aca3", "type": "concept", "title": "Multilevel determinants from biology to policy"}]}, {"id": "90c1c4d3-a6af-4bb2-a6b4-73c9807d1423", "type": "subtopic", "title": "Screening and prevention logic", "description": "Students learn why screening can help, harm, or waste resources depending on test performance and disease context.", "children": [{"id": "d42beb62-e6eb-4b01-a4c1-e4d7e52e3b69", "type": "concept", "title": "Sensitivity, specificity, predictive value, and lead-time bias"}, {"id": "3c912195-24fe-4d10-afe8-f6ca286a2bd0", "type": "concept", "title": "Screening eligibility and risk stratification"}, {"id": "f066473d-eea6-4a3f-8e35-600c566c5ff4", "type": "concept", "title": "Overdiagnosis, overtreatment, and informed choice"}]}, {"id": "a1041243-65ba-4eea-a4e0-991855ba478c", "type": "subtopic", "title": "Chronic disease surveillance", "description": "The gist is to understand how health departments monitor trends and evaluate prevention programs.", "children": [{"id": "8156d56e-3f8d-4d60-9d1f-9477eb2d26f2", "type": "concept", "title": "BRFSS, NHANES, registries, claims, and vital statistics"}, {"id": "e2f8a382-5b7e-481b-a3e0-b3aea3ff5d60", "type": "concept", "title": "Risk-factor monitoring and health indicators"}, {"id": "599c5cef-913b-4561-bb72-25ce98b21788", "type": "concept", "title": "Dashboards, targets, and Healthy People objectives"}]}]}, {"id": "61d1d964-05bc-4343-beda-5696618613bd", "type": "topic", "title": "Cardiovascular Disease and Stroke Prevention", "description": "This topic treats cardiovascular disease and stroke as major preventable causes of death, disability, and inequity, with attention to clinical prevention and upstream policy.", "children": [{"id": "1c425996-c96a-4a6e-b962-bea2eedb8dd1", "type": "subtopic", "title": "Epidemiology of cardiovascular disease", "description": "Students examine why heart disease and stroke remain leading causes of death and disability.", "children": [{"id": "d68beacf-1f30-4a05-a734-85b92ee8ec52", "type": "concept", "title": "Coronary heart disease, heart failure, stroke, and hypertension"}, {"id": "9054fa69-f198-4e06-b499-8954b69a23d0", "type": "concept", "title": "Age, sex, race, geography, and socioeconomic gradients"}, {"id": "bf0b56bc-eaf2-4f2f-9950-2509ad3d68e0", "type": "concept", "title": "Mortality decline, stagnation, and emerging risk patterns"}]}, {"id": "e7790e9c-7f87-426b-9281-3e84d46bcc03", "type": "subtopic", "title": "Risk factors and prevention", "description": "This subtopic links individual risk reduction with upstream prevention.", "children": [{"id": "3b7b64e7-e36b-44fa-a9c1-09aa05185d5d", "type": "concept", "title": "Blood pressure, cholesterol, smoking, diabetes, diet, physical activity, and air pollution"}, {"id": "cafe6d3e-6f8c-4367-ae79-951980043de1", "type": "concept", "title": "Risk prediction and population-wide prevention"}, {"id": "62b3ea52-9c46-4335-a837-e95f2643e018", "type": "concept", "title": "Salt reduction, tobacco control, built environment, and clinical prevention"}]}, {"id": "a2a68356-20fb-4fd4-a754-12866af30c6f", "type": "subtopic", "title": "Systems of care and outcomes", "description": "Learners connect prevention with emergency response, rehabilitation, and long-term secondary prevention.", "children": [{"id": "8e495047-8e34-487c-9a43-332f300c9c50", "type": "concept", "title": "EMS and stroke systems of care"}, {"id": "fe4255ac-b77f-46aa-b848-3d31534e9a99", "type": "concept", "title": "Medication adherence and secondary prevention"}, {"id": "339825f4-aa41-440c-9cd1-3bb52a5937aa", "type": "concept", "title": "Cardiac rehabilitation and community support"}]}]}, {"id": "1ef5460f-0291-4f8f-b54d-defdae95b146", "type": "topic", "title": "Cancer Epidemiology, Screening, and Control", "description": "This section gives students a public health view of cancer across prevention, screening, early detection, treatment access, survivorship, and population monitoring.", "children": [{"id": "d170eb13-a818-4c5a-a4da-1a0bbf450b34", "type": "subtopic", "title": "Cancer burden and natural history", "description": "Students learn cancer as a set of diseases shaped by genetics, exposures, infection, screening, treatment access, and survivorship.", "children": [{"id": "cf191f89-98bf-411b-90d8-35c0f6bbb4c5", "type": "concept", "title": "Incidence, mortality, stage, and survival"}, {"id": "16e2e4c7-3e49-4127-a88f-0737a9270215", "type": "concept", "title": "Cancer registries and population monitoring"}, {"id": "0fc95105-371d-4bc6-bf60-0f70506842bb", "type": "concept", "title": "Latency, carcinogenesis, and modifiable exposure"}]}, {"id": "b254b62a-d49e-4634-9fe7-5c03e9630e4a", "type": "subtopic", "title": "Major preventable cancers", "description": "The point is to see how prevention extends beyond clinical treatment.", "children": [{"id": "6d4843bd-c80f-4342-86bd-2d6d39c66a40", "type": "concept", "title": "Tobacco-related cancers"}, {"id": "088e84cc-9039-4088-bd72-fd894364a438", "type": "concept", "title": "HPV, hepatitis B/C, and infection-associated cancers"}, {"id": "84bd3515-d7ba-44a5-89cd-78a9c8a8b9c0", "type": "concept", "title": "Occupational, environmental, diet, alcohol, and UV exposure"}]}, {"id": "12a1f764-b990-44d2-8bea-8397ef7dd895", "type": "subtopic", "title": "Screening, control, and survivorship", "description": "Learners evaluate evidence-based cancer control strategies and their equity implications.", "children": [{"id": "5e2e91b1-5d3b-4c86-88c2-fd477109d942", "type": "concept", "title": "Breast, cervical, colorectal, lung, and prostate screening controversies"}, {"id": "cfb7b990-b255-46d8-997e-4932a6602b57", "type": "concept", "title": "Access to diagnosis, treatment, and palliative care"}, {"id": "b26c526e-56a8-4e65-b12e-cc5658e78628", "type": "concept", "title": "Survivorship, late effects, and financial toxicity"}]}]}, {"id": "24925a67-871d-4d58-a6c6-9427dddb2f69", "type": "topic", "title": "Diabetes, Obesity, Metabolic Health, and Nutrition-Related Disease", "description": "This topic links metabolic disease to food systems, built environments, chronic care, and inequitable access to prevention and treatment.", "children": [{"id": "676e8538-6305-4b82-8bb2-934ac3be8a0b", "type": "subtopic", "title": "Metabolic disease 